#!/bin/sh\nset -e\n\n# Create temporary directory for a fake qrencode binary\nTMPDIR=$(mktemp -d)\nFAKE_QR="$TMPDIR/qrencode"\ncat > "$FAKE_QR" << 'EOF'\n#!/bin/sh\n# Fake qrencode: expects -o outputfile text...\nwhile [ "$1" != "-o" ]; do shift; done\nshift\nOUT=\"$1\"\nshift\n# Write PNG signature to the output file\nprintf '\\x89PNG\\r\\n\\x1a\\n' > "$OUT"\nEOF\nchmod +x "$FAKE_QR"\n\n# Prepend fake qrencode to PATH\nexport PATH="$TMPDIR:$PATH"\n\n# Create temporary phrases file with a known phrase\nPHRASES_FILE=$(mktemp)\necho "Test phrase" > "$PHRASES_FILE"\n\n# Create temporary file path for QR output\nQR_OUTPUT=$(mktemp)\n\n# Run entrypoint in background with overridden env vars\nPHRASES_FILE="$PHRASES_FILE" QR_OUTPUT="$QR_OUTPUT" ./entrypoint.sh &\nPID=$!\n# Give it a moment to generate the file\nsleep 1\n# Verify QR file exists\nif [ ! -f "$QR_OUTPUT" ]; then\n  echo "QR file not created"\n  kill "$PID"\n  exit 1\nfi\n# Verify PNG signature (first 8 bytes)\nif ! head -c 8 "$QR_OUTPUT" | grep -q $'\\x89PNG\\r\\n\\x1a\\n'; then\n  echo "QR file is not a valid PNG"\n  kill "$PID"\n  exit 1\nfi\n# Clean up\nkill "$PID"\nwait "$PID" 2>/dev/null || true\necho "Test passed"
